#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t; cin >> t;    while(t--) {        int n, r, b;        cin >> n >> r >> b;         int parts = b + 1;         int base = r / parts;     // minimum R in each part        int extra = r % parts;    // extra R to distribute         string ans = "";         for(int i = 0; i < parts; i++) {            // put R's            int cnt = base;            if(extra > 0) {                cnt++;                extra--;            }             ans += string(cnt, 'R');             // put B (except last part)            if(i < b) ans += 'B';        }         cout << ans << '\n';    }}